'use strict';

// MODULES //

var inherit = require( '@stdlib/utils/inherit' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var Socket = require( './socket/main.js' );


// MAIN //

/**
* Shell socket constructor.
*
* @private
* @constructor
* @param {Kernel} kernel - jupyter kernel instance
* @param {Options} options - constructor options
* @param {string} options.ip - client address
* @param {number} options.shell_port - shell port
* @param {string} options.transport - protocol name
* @param {string} options.signature_scheme - signature scheme
* @param {string} options.key - signature key
* @returns {ShellSocket} socket instance
*/
function ShellSocket( kernel, options ) {
	if ( !( this instanceof ShellSocket ) ) {
		return new ShellSocket( kernel, options );
	}

	// Cache a reference to the kernel instance:
	this._kernel = kernel;

	// Call the parent constructor:
	Socket.call(
		this,
		'router',
		options.ip,
		options.shell_port,
		options.transport,
		options.signature_scheme,
		options.key
	);

	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( ShellSocket, Socket );

/**
* Initializes message listener on the socket.
*
* @private
* @name listen
* @memberof ShellSocket.prototype
* @type {Function}
* @returns {void}
*/
setNonEnumerableReadOnly( ShellSocket.prototype, 'listen', function listen() {
	var self;

	// Call the parent method:
	Socket.prototype.listen.call( this );

	self = this;
	this.on( 'request', onRequest );

	/**
	* Callback invoked upon receiving a "request" event.
	*
	* @private
	* @param {Message} message - request message
	* @returns {void}
	*/
	function onRequest( message ) {
		var reqType;
		// Think of validating if `msg_type` exists as a prop to avoid accessor errors

		reqType = message.header.msg_type;
		switch ( reqType ) {
		case 'execute_request':
			self._kernel.emit( 'execute_request', message, message.content );
			return;
		case 'inspect_request':
			self._kernel.emit( 'inspect_request', message, message.content );
			return;
		case 'complete_request':
			self._kernel.emit( 'complete_request', message, message.content );
			return;
		case 'history_request':
			self._kernel.emit( 'history_request', message, message.content );
			return;
		case 'is_complete_request':
			self._kernel.emit( 'is_complete_request', message, message.content );
			return;
		case 'comm_info_request':
			self._kernel.emit( 'comm_info_request', message, message.content );
			return;
		case 'kernel_info_request':
			self._kernel.emit( 'kernel_info_request', message, message.content );
			return;
		default:
			// TODO: use an internal logger for easier maintenance and logging of non-existent requests
		}
		return;
	}
});

// TODO: add methods for graceful closing.


// EXPORTS //

module.exports = ShellSocket;
